public class MathUtils_gcd_TriageGen3Test {







    @Test
    public void testGcdPowerOfTwo() {
        // Covers B1: while ((u & 1) == 0 && (v & 1) == 0 && k < 31)
        assertEquals(8, MathUtils.gcd(16, 24)); // k=3, gcd=8
        assertEquals(2, MathUtils.gcd(2, 6));   // k=1, gcd=2
        assertEquals(1, MathUtils.gcd(3, 5));   // k=0
    }








}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_gcd_TriageGen3Test {









    @Test(expected = ArithmeticException.class)
    public void testGcdOverflowK31() {
        // Covers: if (k == 31) throw ArithmeticException
        // To get k=31, we need u and v to be divisible by 2^31.
        // Since int is 32-bit signed, 2^31 is actually Integer.MIN_VALUE.
        // Integer.MIN_VALUE is 1000...000 in binary (only the sign bit is set, but in 2's complement it is -2147483648)
        // The loop condition (u & 1) == 0 will hold for Integer.MIN_VALUE.
        MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
    }






}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_gcd_TriageGen3Test {











    @Test
    public void testGcdB2B3Paths() {
        // Covers B2/B3 different initialization paths for t

        // Path 1: u was odd, v may be even (t = v)
        // u = -3, v = -4 -> k=0. (u & 1) == 1 is true. t = v = -4.
        assertEquals(1, MathUtils.gcd(3, 4));

        // Path 2: u was even, v is odd (t = -(u / 2))
        // u = -4, v = -3 -> k=0. (u & 1) == 1 is false. t = -(-4/2) = 2.
        assertEquals(1, MathUtils.gcd(4, 3));
    }




}

